def four_point_mass(xyz,tet): # Reproduce the separately identified native four-point quadratic-tetrahedron mass rule.
    quadrature=np.full((4,4),.1381966011250105);np.fill_diagonal(quadrature,.5854101966249685);C=np.zeros((10,10)) # Use the documented C3D10 Gaussian points, which do not exactly integrate degree-four mass products.
    for L in quadrature: # Integrate actual quadratic shape products using native quadrature.
        N=np.r_[L*(2*L-1),[4*L[i]*L[j] for i,j in EDGES]];C+=np.outer(N,N)/4 # Retain underintegration explicitly rather than changing the exact production mass.
    corners=xyz[tet[:,:4]];volume=np.abs(np.linalg.det(np.stack([corners[:,i]-corners[:,0] for i in [1,2,3]],axis=2)))/6;local=np.kron(C,np.eye(3))[None,:,:]*(RHO*volume[:,None,None]);dof=(tet[:,:,None]*3+np.arange(3)).reshape(-1,30) # Assemble the quadrature-matched diagnostic mass only.
    return coo_matrix((local.ravel(),(np.repeat(dof,30,axis=1).ravel(),np.tile(dof,(1,30)).ravel())),shape=(xyz.size,xyz.size)).tocsr() # Return native-rule diagnostic matrix.
def native_matrix_check(family): # Resolve apparent modal discrepancy by comparing the matrices used by the actual native solver.
    folder=DYN/'native'/f'{family}_reference'/'matrix';folder.mkdir(parents=True,exist_ok=True);source=DYN/'native'/f'{family}_reference'/'frequency/model.inp';(folder/'model.inp').write_text(source.read_text().replace('*FREQUENCY','*FREQUENCY,SOLVER=MATRIXSTORAGE')) # Request original CalculiX stiffness and mass export without changing source constraints.
    with (folder/'solver.log').open('w') as stream: result=subprocess.run([str(CCX),'-i','model'],cwd=folder,stdout=stream,stderr=subprocess.STDOUT,timeout=60) # Execute actual native matrix generation.
    assert result.returncode==0 and (folder/'model.mas').exists() # Reject missing physical evidence.
    def read_matrix(name): # Parse the native upper-triangular coordinate matrix.
        values=np.loadtxt(folder/name);r=values[:,0].astype(int)-1;c=values[:,1].astype(int)-1;A=coo_matrix((values[:,2],(r,c))).tocsr();return A+A.T-diags(A.diagonal()) # Recover exact native symmetric sparse operator.
    m=modal_model(family+'_reference',count=24);native_k=read_matrix('model.sti');native_m=read_matrix('model.mas');four=four_point_mass(m['data']['xyz'],m['data']['tet'])[m['free']][:,m['free']];dofs=np.array([(int(v.split('.')[0])-1)*3+int(v.split('.')[1])-1 for v in (folder/'model.dof').read_text().splitlines()]);assert np.array_equal(dofs,m['free']) # Verify native DOF ordering before any matrix comparisons.
    relative=lambda a,b:float(np.sqrt((a-b).power(2).sum()/b.power(2).sum()));native_eigen=eigsh(native_k,24,M=native_m,sigma=0,which='LM',return_eigenvectors=False);native_hz=np.sqrt(native_eigen)/(2*np.pi);four_eigen=eigsh(m['K'],24,M=four,sigma=0,which='LM',return_eigenvectors=False);four_hz=np.sqrt(four_eigen)/(2*np.pi);printed=[] # Solve both native exported and independently assembled native-rule eigenproblems.
    for line in (source.parent/'model.dat').read_text().split('P A R T I C I P A T I O N')[0].splitlines(): # Read actual native eigenfrequency table.
        if re.match(r'^\s*\d+\s+[-+0-9.E]+\s+[-+0-9.E]+\s+[-+0-9.E]+\s+[-+0-9.E]+\s*$',line): printed.append(float(line.split()[3])) # Ignore nonfrequency result records.
    exact_hz=m['omega']/(2*np.pi);record={'family':family,'native_K_relative_independent':relative(native_k,m['K']),'native_M_relative_four_point':relative(native_m,four),'native_M_relative_exact_mass':relative(native_m,m['M']),'native_printed_frequency_vs_export_eigensolve_max_relative':float(np.max(np.abs(native_hz-printed[:24])/native_hz)),'native_rule_frequency_vs_independent_four_point_max_relative':float(np.max(np.abs(native_hz-four_hz)/native_hz)),'native_frequency_vs_exact_mass_max_relative':float(np.max(np.abs(native_hz-exact_hz)/exact_hz)),'exact_mass_Hz':exact_hz.tolist(),'native_four_point_Hz':native_hz.tolist(),'input_sha256':sha(folder/'model.inp'),'mass_sha256':sha(folder/'model.mas'),'explanation':'Native C3D10 uses four-point underintegrated Ni*Nj mass; production dynamics retain exact degree-four consistent mass. Like-for-like native-rule eigenproblem is compared separately.'};record['status']='PASS' if record['native_M_relative_four_point']<1e-6 and record['native_rule_frequency_vs_independent_four_point_max_relative']<1e-6 else 'HOLD' # Resolve actual rule difference without relaxing the original consistency threshold.
